import React, { useState, useEffect } from 'react';
import { productsAPI, ordersAPI } from '../services/api';

const Dashboard = ({ user }) => {
  const [activeTab, setActiveTab] = useState('orders');
  const [orders, setOrders] = useState([]);
  const [products, setProducts] = useState([]);
  const [newProduct, setNewProduct] = useState({
    name: '', description: '', price: '', category: '', image: '', stock: ''
  });

  useEffect(() => {
    if (user) {
      fetchOrders();
      if (user.role === 'seller') {
        fetchProducts();
      }
    }
  }, [user]);

  const fetchOrders = async () => {
    try {
      const response = await ordersAPI.getMyOrders();
      setOrders(response.data);
    } catch (error) {
      console.error('Error fetching orders:', error);
    }
  };

  const fetchProducts = async () => {
    try {
      const response = await productsAPI.getAll();
      setProducts(response.data.filter(p => p.seller._id === user.id));
    } catch (error) {
      console.error('Error fetching products:', error);
    }
  };

  const handleCreateProduct = async (e) => {
    e.preventDefault();
    try {
      await productsAPI.create({
        ...newProduct,
        price: parseFloat(newProduct.price),
        stock: parseInt(newProduct.stock)
      });
      setNewProduct({ name: '', description: '', price: '', category: '', image: '', stock: '' });
      fetchProducts();
      alert('Product created successfully!');
    } catch (error) {
      alert('Error creating product: ' + (error.response?.data?.message || 'Unknown error'));
    }
  };

  if (!user) return <div className="container">Please login to access dashboard</div>;

  return (
    <div className="container">
      <div className="dashboard">
        <div className="sidebar">
          <h3>Dashboard</h3>
          <ul>
            <li 
              className={activeTab === 'orders' ? 'active' : ''}
              onClick={() => setActiveTab('orders')}
            >
              My Orders
            </li>
            {user.role === 'seller' && (
              <>
                <li 
                  className={activeTab === 'products' ? 'active' : ''}
                  onClick={() => setActiveTab('products')}
                >
                  My Products
                </li>
                <li 
                  className={activeTab === 'add-product' ? 'active' : ''}
                  onClick={() => setActiveTab('add-product')}
                >
                  Add Product
                </li>
              </>
            )}
          </ul>
        </div>

        <div className="main-content">
          {activeTab === 'orders' && (
            <div>
              <h3>My Orders</h3>
              {orders.map(order => (
                <div key={order._id} className="order-card">
                  <p><strong>Order ID:</strong> {order._id}</p>
                  <p><strong>Total:</strong> ₹{order.total}</p>
                  <p><strong>Status:</strong> <span style={{textTransform: 'capitalize', color: '#667eea'}}>{order.status}</span></p>
                  <p><strong>Date:</strong> {new Date(order.createdAt).toLocaleDateString()}</p>
                </div>
              ))}
            </div>
          )}

          {activeTab === 'products' && user.role === 'seller' && (
            <div>
              <h3>My Products</h3>
              <div className="products-grid">
                {products.map(product => (
                  <div key={product._id} className="product-card">
                    <img src={product.image || 'https://via.placeholder.com/300x200'} alt={product.name} />
                    <h4>{product.name}</h4>
                    <p className="price">₹{product.price}</p>
                    <p>Stock: {product.stock}</p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {activeTab === 'add-product' && user.role === 'seller' && (
            <div>
              <h3>Add New Product</h3>
              <form onSubmit={handleCreateProduct} className="form">
                <div className="form-group">
                  <label>Name:</label>
                  <input
                    type="text"
                    value={newProduct.name}
                    onChange={(e) => setNewProduct({ ...newProduct, name: e.target.value })}
                    required
                  />
                </div>
                <div className="form-group">
                  <label>Description:</label>
                  <textarea
                    value={newProduct.description}
                    onChange={(e) => setNewProduct({ ...newProduct, description: e.target.value })}
                    required
                  />
                </div>
                <div className="form-group">
                  <label>Price:</label>
                  <input
                    type="number"
                    step="0.01"
                    value={newProduct.price}
                    onChange={(e) => setNewProduct({ ...newProduct, price: e.target.value })}
                    required
                  />
                </div>
                <div className="form-group">
                  <label>Category:</label>
                  <input
                    type="text"
                    value={newProduct.category}
                    onChange={(e) => setNewProduct({ ...newProduct, category: e.target.value })}
                    required
                  />
                </div>
                <div className="form-group">
                  <label>Image URL:</label>
                  <input
                    type="url"
                    value={newProduct.image}
                    onChange={(e) => setNewProduct({ ...newProduct, image: e.target.value })}
                  />
                </div>
                <div className="form-group">
                  <label>Stock:</label>
                  <input
                    type="number"
                    value={newProduct.stock}
                    onChange={(e) => setNewProduct({ ...newProduct, stock: e.target.value })}
                    required
                  />
                </div>
                <button type="submit" className="btn">Add Product</button>
              </form>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
